// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("no filters: just the order and the limit", () -> {
        eq(findOrders(new Filter(null, null, null, 20)), new Sql(SELECT + " ORDER BY id LIMIT ?", List.of(20)));
    });
    test("a quote in the name is a parameter, never SQL text", () -> {
        var sql = findOrders(new Filter("O'Brien", null, null, 20));
        eq(List.of(sql.text(), sql.params()), List.of(SELECT + " WHERE LOWER(customer) LIKE ? ESCAPE '!' ORDER BY id LIMIT ?", List.of("%o'brien%", 20)));
    });
    test("LIKE wildcards and the escape character in user text are escaped", () -> {
        eq(List.of(findOrders(new Filter("50%", null, null, 5)).params().get(0), findOrders(new Filter("a_b!", null, null, 5)).params().get(0)), List.of("%50!%%", "%a!_b!!%"));
    });
    test("one placeholder per status, conditions joined in order", () -> {
        var sql = findOrders(new Filter("ana", List.of("PAID", "SHIPPED"), 1000L, 10));
        eq(List.of(sql.text(), sql.params()), List.of(
            SELECT + " WHERE LOWER(customer) LIKE ? ESCAPE '!' AND status IN (?, ?) AND total_cents >= ? ORDER BY id LIMIT ?",
            List.of("%ana%", "PAID", "SHIPPED", 1000L, 10)));
    });
    test("an empty status list matches nothing and adds no parameter", () -> {
        eq(findOrders(new Filter(null, List.of(), null, 10)), new Sql(SELECT + " WHERE 1 = 0 ORDER BY id LIMIT ?", List.of(10)));
    });
    test("the limit must be 1 to 100 (boundary)", () -> {
        raises(IllegalArgumentException.class, () -> findOrders(new Filter(null, null, null, 0)));
        raises(IllegalArgumentException.class, () -> findOrders(new Filter(null, null, null, 101)));
        eq(List.of(findOrders(new Filter(null, null, null, 1)).params(), findOrders(new Filter(null, null, null, 100)).params()), List.of(List.of(1), List.of(100)));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("success: auto-commit off, the work, commit, auto-commit restored", () -> {
        var db = new FakeDb();
        var result = inTransaction(db.connection(), Exercise::debit);
        eq(List.of(result, db.log), List.of(1, List.of("autoCommit=false", "update " + DEBIT + " [500, 7]", "commit", "autoCommit=true")));
    });
    test("an SQLException rolls back and reaches the caller", () -> {
        var db = new FakeDb();
        db.failing = sql -> sql.equals(DEBIT);
        raises(SQLException.class, () -> inTransaction(db.connection(), Exercise::debit), "constraint violated");
        eq(db.log, List.of("autoCommit=false", "update " + DEBIT + " [500, 7]", "rollback", "autoCommit=true"));
    });
    test("a RuntimeException from the work rolls back too", () -> {
        var db = new FakeDb();
        raises(IllegalStateException.class, () -> inTransaction(db.connection(), c -> { debit(c); throw new IllegalStateException("limit exceeded"); }), "limit exceeded");
        eq(db.log.subList(2, 4), List.of("rollback", "autoCommit=true"));
    });
    test("a failed rollback travels as suppressed; the first exception wins", () -> {
        var db = new FakeDb();
        db.failing = sql -> sql.equals(DEBIT);
        db.failRollback = true;
        try {
            inTransaction(db.connection(), Exercise::debit);
            eq("no exception", "SQLException");
        } catch (SQLException e) {
            eq(List.of(e.getMessage(), e.getSuppressed().length, e.getSuppressed()[0].getMessage()), List.of("constraint violated", 1, "rollback failed"));
        }
    });
    test("a connection that arrived in manual-commit mode is left that way, and never closed (boundary)", () -> {
        var db = new FakeDb();
        db.autoCommit = false;
        inTransaction(db.connection(), Exercise::debit);
        eq(List.of(db.autoCommit, db.log.contains("close"), db.log.get(db.log.size() - 1)), List.of(false, false, "autoCommit=false"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

