public static void main(String[] args) {
    test("five rows in chunks of two: batches of 2, 2 and 1", () -> {
        var db = new FakeDb();
        int n = insertAll(db.connection(), rows(5), 2);
        eq(List.of(n, batches(db)), List.of(5, List.of("[[sku-1, 1], [sku-2, 2]]", "[[sku-3, 3], [sku-4, 4]]", "[[sku-5, 5]]")));
    });
    test("rows that divide evenly send no empty batch", () -> {
        var db = new FakeDb();
        eq(List.of(insertAll(db.connection(), rows(4), 2), batches(db).size()), List.of(4, 2));
    });
    test("all chunks share one transaction and one commit", () -> {
        var db = new FakeDb();
        insertAll(db.connection(), rows(5), 2);
        eq(List.of(db.log.get(0), db.log.stream().filter("commit"::equals).count(), db.log.get(db.log.size() - 1)), List.of("autoCommit=false", 1L, "autoCommit=true"));
    });
    test("a failing batch rolls back everything and commits nothing", () -> {
        var db = new FakeDb();
        db.failing = sql -> sql.equals(INSERT_SQL);
        raises(SQLException.class, () -> insertAll(db.connection(), rows(3), 2), "batch failed");
        eq(List.of(db.log.contains("commit"), db.log.contains("rollback"), db.autoCommit), List.of(false, true, true));
    });
    test("no rows touch nothing; a chunk below 1 is refused (boundary)", () -> {
        var db = new FakeDb();
        eq(List.of(insertAll(db.connection(), List.of(), 2), db.log), List.of(0, List.of()));
        raises(IllegalArgumentException.class, () -> insertAll(db.connection(), rows(1), 0));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

