public static void main(String[] args) {
    test("each order gets its own lines, an order without lines an empty list", () -> {
        var db = shop(ORDERS, LINES);
        var views = ordersWithLines(db.connection(), "ana", 10);
        eq(views, List.of(
            new OrderView(1, List.of(new Line("cake", 1), new Line("tea", 2))), new OrderView(2, List.of()),
            new OrderView(3, List.of(new Line("jam", 1))), new OrderView(4, List.of()), new OrderView(5, List.of(new Line("milk", 3)))));
    });
    test("five orders cost two queries, not six", () -> {
        var db = shop(ORDERS, LINES);
        ordersWithLines(db.connection(), "ana", 10);
        eq(queries(db), List.of("query " + ORDERS_SQL + " [ana]", "query " + LINES_PREFIX + "?, ?, ?, ?, ?" + LINES_SUFFIX + " [1, 2, 3, 4, 5]"));
    });
    test("ids are sent in chunks of at most maxIds", () -> {
        var db = shop(ORDERS, LINES);
        var views = ordersWithLines(db.connection(), "ana", 2);
        eq(List.of(queries(db).size(), queries(db).get(3), views.get(4).lines()), List.of(4, "query " + LINES_PREFIX + "?" + LINES_SUFFIX + " [5]", List.of(new Line("milk", 3))));
    });
    test("another customer's lines never show up", () -> {
        var db = shop(ORDERS, LINES);
        eq(ordersWithLines(db.connection(), "bo", 10), List.of(new OrderView(9, List.of(new Line("bread", 1)))));
    });
    test("a customer with no orders costs one query and no IN () (boundary)", () -> {
        var db = shop(ORDERS, LINES);
        eq(List.of(ordersWithLines(db.connection(), "cy", 10), queries(db).size()), List.of(List.of(), 1));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

