public static void main(String[] args) {
    test("a NULL discount stays null", () -> {
        var rs = rows(FakeDb.row("id", 7L, "name", "Ana", "credit_limit", "250.00"));
        rs.next();
        eq(map(rs), new Customer(7, "Ana", null, new BigDecimal("250.00")));
    });
    test("a real zero discount stays zero", () -> {
        var rs = rows(FakeDb.row("id", 8L, "name", "Bo", "discount_pct", 0));
        rs.next();
        eq(map(rs).discountPct(), 0);
    });
    test("NULL and values in the same row: each column judged on its own", () -> {
        var rs = rows(FakeDb.row("id", 9L, "name", "Cy", "credit_limit", "10.50"), FakeDb.row("id", 10L, "name", "Di", "discount_pct", 15));
        eq(readAll(rs), List.of(new Customer(9, "Cy", null, new BigDecimal("10.50")), new Customer(10, "Di", 15, null)));
    });
    test("readAll keeps the row order", () -> {
        var rs = rows(FakeDb.row("id", 2L, "name", "B", "discount_pct", 5), FakeDb.row("id", 1L, "name", "A", "discount_pct", 10));
        eq(readAll(rs).stream().map(Customer::id).toList(), List.of(2L, 1L));
    });
    test("no rows give an empty list (boundary)", () -> {
        eq(readAll(rows()), List.of());
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("one row updated: the new version comes back", () -> {
        var db = new FakeDb();
        eq(rename(db.connection(), 7, 3, "Ana Lima"), 4L);
    });
    test("the name, the id and the version are bound in placeholder order", () -> {
        var db = new FakeDb();
        rename(db.connection(), 7, 3, "Ana Lima");
        eq(db.log, List.of("update " + RENAME_SQL + " [Ana Lima, 7, 3]"));
    });
    test("zero rows means someone saved first", () -> {
        var db = new FakeDb();
        db.updateCount = q -> 0;
        raises(StaleUpdate.class, () -> rename(db.connection(), 7, 3, "Ana Lima"), "customer 7 changed since version 3");
    });
    test("two rows is a broken id, not a conflict", () -> {
        var db = new FakeDb();
        db.updateCount = q -> 2;
        raises(IllegalStateException.class, () -> rename(db.connection(), 7, 3, "Ana Lima"));
    });
    test("a blank name is refused before any SQL runs (boundary)", () -> {
        var db = new FakeDb();
        raises(IllegalArgumentException.class, () -> rename(db.connection(), 7, 3, "  "));
        raises(IllegalArgumentException.class, () -> rename(db.connection(), 7, 3, null));
        eq(db.log, List.of());
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

