// ─────────────────────────────────────────────────────────────────────────
//  01 · parameters, not concatenation★★☆
//  concepts: bind parameters · one placeholder per IN value · escaping LIKE wildcards · empty IN
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    record Filter(String nameContains, List<String> statuses, Long minTotalCents, int limit) {}
    record Sql(String text, List<Object> params) {}

    static final String SELECT = "SELECT id, customer, status, total_cents FROM orders";


    static Sql findOrders(Filter f) {
        if (f.limit() < 1 || f.limit() > 100) throw new IllegalArgumentException("limit must be 1..100");
        var where = new ArrayList<String>();
        var params = new ArrayList<Object>();
        if (f.nameContains() != null) {
            String text = f.nameContains().toLowerCase(Locale.ROOT).replace("!", "!!").replace("%", "!%").replace("_", "!_");
            where.add("LOWER(customer) LIKE ? ESCAPE '!'");
            params.add("%" + text + "%");
        }
        if (f.statuses() != null) {
            if (f.statuses().isEmpty()) {
                where.add("1 = 0");
            } else {
                where.add("status IN (" + String.join(", ", Collections.nCopies(f.statuses().size(), "?")) + ")");
                params.addAll(f.statuses());
            }
        }
        if (f.minTotalCents() != null) {
            where.add("total_cents >= ?");
            params.add(f.minTotalCents());
        }
        params.add(f.limit());
        String text = SELECT + (where.isEmpty() ? "" : " WHERE " + String.join(" AND ", where)) + " ORDER BY id LIMIT ?";
        return new Sql(text, params);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("no filters: just the order and the limit", () -> {
            eq(findOrders(new Filter(null, null, null, 20)), new Sql(SELECT + " ORDER BY id LIMIT ?", List.of(20)));
        });
        test("a quote in the name is a parameter, never SQL text", () -> {
            var sql = findOrders(new Filter("O'Brien", null, null, 20));
            eq(List.of(sql.text(), sql.params()), List.of(SELECT + " WHERE LOWER(customer) LIKE ? ESCAPE '!' ORDER BY id LIMIT ?", List.of("%o'brien%", 20)));
        });
        test("LIKE wildcards and the escape character in user text are escaped", () -> {
            eq(List.of(findOrders(new Filter("50%", null, null, 5)).params().get(0), findOrders(new Filter("a_b!", null, null, 5)).params().get(0)), List.of("%50!%%", "%a!_b!!%"));
        });
        test("one placeholder per status, conditions joined in order", () -> {
            var sql = findOrders(new Filter("ana", List.of("PAID", "SHIPPED"), 1000L, 10));
            eq(List.of(sql.text(), sql.params()), List.of(
                SELECT + " WHERE LOWER(customer) LIKE ? ESCAPE '!' AND status IN (?, ?) AND total_cents >= ? ORDER BY id LIMIT ?",
                List.of("%ana%", "PAID", "SHIPPED", 1000L, 10)));
        });
        test("an empty status list matches nothing and adds no parameter", () -> {
            eq(findOrders(new Filter(null, List.of(), null, 10)), new Sql(SELECT + " WHERE 1 = 0 ORDER BY id LIMIT ?", List.of(10)));
        });
        test("the limit must be 1 to 100 (boundary)", () -> {
            raises(IllegalArgumentException.class, () -> findOrders(new Filter(null, null, null, 0)));
            raises(IllegalArgumentException.class, () -> findOrders(new Filter(null, null, null, 101)));
            eq(List.of(findOrders(new Filter(null, null, null, 1)).params(), findOrders(new Filter(null, null, null, 100)).params()), List.of(List.of(1), List.of(100)));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

javadrills/14-jdbc-data-access/01-parame.explanation:
Collect conditions and parameters side by side, so they cannot drift apart:

```java
if (f.nameContains() != null) {
    String text = f.nameContains().toLowerCase(Locale.ROOT).replace("!", "!!").replace("%", "!%").replace("_", "!_");
    where.add("LOWER(customer) LIKE ? ESCAPE '!'");
    params.add("%" + text + "%");
}
if (f.statuses() != null) {
    if (f.statuses().isEmpty()) where.add("1 = 0");
    else { where.add("status IN (" + String.join(", ", Collections.nCopies(f.statuses().size(), "?")) + ")"); params.addAll(f.statuses()); }
}
```

Escape `!` first, or the escapes you add are escaped again. The tests catch the plausible wrong builders. Putting the name into the SQL text with quotes breaks on `O'Brien` and is an injection (the quote test checks the text holds no user input). Passing `50%` unescaped matches everything (the wildcard test wants `%50!%%`). Joining the statuses into one parameter (`"PAID,SHIPPED"`) compares the column with one odd string, and an empty list rendered as `IN ()` is invalid SQL (the boundary test wants `1 = 0`).

