// ─────────────────────────────────────────────────────────────────────────
//  02 · a transaction template★★★
//  concepts: setAutoCommit(false) · rollback on any failure · suppressed exceptions · restore the connection
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.lang.reflect.*;
import java.math.*;
import java.sql.*;
import java.util.*;
import java.util.function.*;

class Exercise {

    /** Given: one statement as the fake saw it. */
    record Query(String sql, List<Object> params) {}

    /** Given: a scripted, in-memory fake of java.sql (dynamic proxies). Every statement and transaction call is logged. */
    static final class FakeDb {
        final List<String> log = new ArrayList<>();
        Function<Query, List<Map<String, Object>>> answers = q -> List.of();
        ToIntFunction<Query> updateCount = q -> 1;
        Predicate<String> failing = sql -> false;
        boolean failRollback;
        boolean autoCommit = true;

        interface Answer { Object apply(String method, Object[] args) throws Exception; }

        @SuppressWarnings("unchecked")
        static <T> T proxy(Class<T> type, Answer answer) {
            return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] { type }, (self, m, a) -> {
                if (m.getDeclaringClass() == Object.class) return m.getName().equals("equals") ? self == a[0] : m.getName().equals("hashCode") ? System.identityHashCode(self) : "fake " + type.getSimpleName();
                return answer.apply(m.getName(), a == null ? new Object[0] : a);
            });
        }

        Connection connection() {
            return proxy(Connection.class, (method, args) -> switch (method) {
                case "getAutoCommit" -> autoCommit;
                case "setAutoCommit" -> { autoCommit = (Boolean) args[0]; log.add("autoCommit=" + args[0]); yield null; }
                case "commit" -> { log.add("commit"); yield null; }
                case "rollback" -> { log.add("rollback"); if (failRollback) throw new SQLException("rollback failed"); yield null; }
                case "close" -> { log.add("close"); yield null; }
                case "prepareStatement" -> statement((String) args[0]);
                default -> throw new UnsupportedOperationException("the fake has no Connection." + method);
            });
        }

        PreparedStatement statement(String sql) {
            var params = new TreeMap<Integer, Object>();
            var batch = new ArrayList<List<Object>>();
            return proxy(PreparedStatement.class, (method, args) -> switch (method) {
                case "setObject", "setString", "setLong", "setInt", "setBigDecimal" -> { params.put((Integer) args[0], args[1]); yield null; }
                case "setNull" -> { params.put((Integer) args[0], null); yield null; }
                case "clearParameters" -> { params.clear(); yield null; }
                case "executeQuery" -> {
                    var q = new Query(sql, new ArrayList<>(params.values()));
                    log.add("query " + sql + " " + q.params());
                    if (failing.test(sql)) throw new SQLException("query failed");
                    yield resultSet(answers.apply(q));
                }
                case "executeUpdate" -> {
                    var q = new Query(sql, new ArrayList<>(params.values()));
                    log.add("update " + sql + " " + q.params());
                    if (failing.test(sql)) throw new SQLException("constraint violated");
                    yield updateCount.applyAsInt(q);
                }
                case "addBatch" -> { batch.add(new ArrayList<>(params.values())); yield null; }
                case "executeBatch" -> {
                    log.add("batch " + sql + " " + batch);
                    if (failing.test(sql)) throw new SQLException("batch failed");
                    int[] counts = new int[batch.size()];
                    Arrays.fill(counts, 1);
                    batch.clear();
                    yield counts;
                }
                case "close" -> null;
                default -> throw new UnsupportedOperationException("the fake has no PreparedStatement." + method);
            });
        }

        /** A forward-only result set over rows (column label -> value; a missing or null value is SQL NULL). */
        static ResultSet resultSet(List<Map<String, Object>> rows) {
            int[] at = { -1 };
            boolean[] lastNull = { false };
            return proxy(ResultSet.class, (method, args) -> {
                if (method.equals("next")) return ++at[0] < rows.size();
                if (method.equals("close")) return null;
                if (method.equals("wasNull")) return lastNull[0];
                if (!method.startsWith("get") || args.length == 0 || !(args[0] instanceof String label)) throw new UnsupportedOperationException("the fake has no ResultSet." + method + " with these arguments");
                if (at[0] < 0 || at[0] >= rows.size()) throw new SQLException("no current row");
                Object v = rows.get(at[0]).get(label);
                lastNull[0] = v == null;
                return switch (method) {
                    case "getLong" -> v == null ? 0L : ((Number) v).longValue();
                    case "getInt" -> v == null ? 0 : ((Number) v).intValue();
                    case "getString" -> v == null ? null : v.toString();
                    case "getBigDecimal" -> v == null ? null : new BigDecimal(v.toString());
                    case "getObject" -> v;
                    default -> throw new UnsupportedOperationException("the fake has no ResultSet." + method);
                };
            });
        }

        static Map<String, Object> row(Object... labelsAndValues) {
            var m = new HashMap<String, Object>();
            for (int i = 0; i < labelsAndValues.length; i += 2) m.put((String) labelsAndValues[i], labelsAndValues[i + 1]);
            return m;
        }
    }


    interface Work<T> { T run(Connection c) throws SQLException; }


    static <T> T inTransaction(Connection c, Work<T> work) throws SQLException {
        throw new UnsupportedOperationException("TODO: auto-commit off, commit or roll back, restore auto-commit");
    }

    static final String DEBIT = "UPDATE accounts SET balance = balance - ? WHERE id = ?";

    static int debit(Connection c) throws SQLException {
        try (var ps = c.prepareStatement(DEBIT)) {
            ps.setLong(1, 500L);
            ps.setLong(2, 7L);
            return ps.executeUpdate();
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("success: auto-commit off, the work, commit, auto-commit restored", () -> {
            var db = new FakeDb();
            var result = inTransaction(db.connection(), Exercise::debit);
            eq(List.of(result, db.log), List.of(1, List.of("autoCommit=false", "update " + DEBIT + " [500, 7]", "commit", "autoCommit=true")));
        });
        test("an SQLException rolls back and reaches the caller", () -> {
            var db = new FakeDb();
            db.failing = sql -> sql.equals(DEBIT);
            raises(SQLException.class, () -> inTransaction(db.connection(), Exercise::debit), "constraint violated");
            eq(db.log, List.of("autoCommit=false", "update " + DEBIT + " [500, 7]", "rollback", "autoCommit=true"));
        });
        test("a RuntimeException from the work rolls back too", () -> {
            var db = new FakeDb();
            raises(IllegalStateException.class, () -> inTransaction(db.connection(), c -> { debit(c); throw new IllegalStateException("limit exceeded"); }), "limit exceeded");
            eq(db.log.subList(2, 4), List.of("rollback", "autoCommit=true"));
        });
