    interface Work<T> { T run(Connection c) throws SQLException; }


    static <T> T inTransaction(Connection c, Work<T> work) throws SQLException {
        boolean before = c.getAutoCommit();
        c.setAutoCommit(false);
        try {
            T result = work.run(c);
            c.commit();
            return result;
        } catch (SQLException | RuntimeException e) {
            try {
                c.rollback();
            } catch (SQLException r) {
                e.addSuppressed(r);
            }
