            raises(IllegalStateException.class, () -> inTransaction(db.connection(), c -> { debit(c); throw new IllegalStateException("limit exceeded"); }), "limit exceeded");
            eq(db.log.subList(2, 4), List.of("rollback", "autoCommit=true"));
        });
        test("a failed rollback travels as suppressed; the first exception wins", () -> {
            var db = new FakeDb();
            db.failing = sql -> sql.equals(DEBIT);
            db.failRollback = true;
            try {
                inTransaction(db.connection(), Exercise::debit);
                eq("no exception", "SQLException");
            } catch (SQLException e) {
                eq(List.of(e.getMessage(), e.getSuppressed().length, e.getSuppressed()[0].getMessage()), List.of("constraint violated", 1, "rollback failed"));
            }
        });
        test("a connection that arrived in manual-commit mode is left that way, and never closed (boundary)", () -> {
            var db = new FakeDb();
            db.autoCommit = false;
            inTransaction(db.connection(), Exercise::debit);
            eq(List.of(db.autoCommit, db.log.contains("close"), db.log.get(db.log.size() - 1)), List.of(false, false, "autoCommit=false"));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

javadrills/14-jdbc-data-access/02-a-tran.explanation:
Commit inside the `try`, roll back in the `catch`, restore in `finally`:

```java
boolean before = c.getAutoCommit();
c.setAutoCommit(false);
try {
    T result = work.run(c);
    c.commit();
    return result;
} catch (SQLException | RuntimeException e) {
    try { c.rollback(); } catch (SQLException r) { e.addSuppressed(r); }
    throw e;
} finally {
    c.setAutoCommit(before);
}
```

The tests read the fake's log, so each step is checked in order. Catching only `SQLException` leaves a `RuntimeException` from the work uncommitted but not rolled back (the runtime-failure test expects `rollback`). Letting the rollback's exception escape replaces the original: the caller sees "rollback failed" instead of "constraint violated" (the suppressed test). Setting auto-commit back to `true` instead of the remembered value changes a connection that arrived in manual mode (the boundary test). Closing the connection in `finally` takes it away from its owner (the log would show `close`).

