            ps.setString(1, newName);
            ps.setLong(2, id);
            ps.setLong(3, expectedVersion);
            int rows = ps.executeUpdate();
            if (rows == 0) throw new StaleUpdate("customer " + id + " changed since version " + expectedVersion);
            if (rows > 1) throw new IllegalStateException(rows + " rows matched id " + id);
            return expectedVersion + 1;
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("one row updated: the new version comes back", () -> {
            var db = new FakeDb();
            eq(rename(db.connection(), 7, 3, "Ana Lima"), 4L);
        });
        test("the name, the id and the version are bound in placeholder order", () -> {
            var db = new FakeDb();
            rename(db.connection(), 7, 3, "Ana Lima");
            eq(db.log, List.of("update " + RENAME_SQL + " [Ana Lima, 7, 3]"));
        });
        test("zero rows means someone saved first", () -> {
            var db = new FakeDb();
            db.updateCount = q -> 0;
            raises(StaleUpdate.class, () -> rename(db.connection(), 7, 3, "Ana Lima"), "customer 7 changed since version 3");
        });
        test("two rows is a broken id, not a conflict", () -> {
            var db = new FakeDb();
            db.updateCount = q -> 2;
            raises(IllegalStateException.class, () -> rename(db.connection(), 7, 3, "Ana Lima"));
        });
        test("a blank name is refused before any SQL runs (boundary)", () -> {
            var db = new FakeDb();
            raises(IllegalArgumentException.class, () -> rename(db.connection(), 7, 3, "  "));
            raises(IllegalArgumentException.class, () -> rename(db.connection(), 7, 3, null));
            eq(db.log, List.of());
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

javadrills/14-jdbc-data-access/06-check-.explanation:
Bind in placeholder order and let the row count decide:

```java
try (var ps = c.prepareStatement(RENAME_SQL)) {
    ps.setString(1, newName);
    ps.setLong(2, id);
    ps.setLong(3, expectedVersion);
    int rows = ps.executeUpdate();
    if (rows == 0) throw new StaleUpdate("customer " + id + " changed since version " + expectedVersion);
    if (rows > 1) throw new IllegalStateException(rows + " rows matched id " + id);
    return expectedVersion + 1;
}
```

The tests script the fake's row count. Ignoring the count and returning `expectedVersion + 1` reports success for a stale write (the conflict test expects `StaleUpdate`). Treating "not 1" as stale hides a duplicate-id bug behind a retryable error (the two-rows test expects `IllegalStateException`). Binding `id` and `expectedVersion` the other way round matches the wrong row or none (the parameters test reads the bound values). Checking the name after running the update has already written it (the boundary test expects an empty log).
